/**
 * Service worker registration and the update policy.
 *
 * The service worker (generated by vite-plugin-pwa, configured in
 * vite.config.ts) precaches the app shell — index.html plus the hashed JS/CSS
 * — so launches from the home screen don't wait on the network for the bundle.
 * Everything else (couch, backends, audio) passes through to the network.
 *
 * Updates: a deploy produces a new service worker, which installs in the
 * background and then *waits*. It is never activated mid-screen: a toddler
 * mid-question must not get a surprise reload. Instead the next in-app
 * navigation to a different page is turned into a full page load of its
 * destination under the new worker — the same trick the guest-namespace guard
 * uses (router/index.ts). Until then the old worker keeps serving the old
 * build's files, which matters because each deploy is a fresh directory: the
 * server no longer has the old build's chunks. A reload (F5) also switches,
 * if the new worker is ready within a few seconds of it
 * (RELOAD_UPGRADE_WINDOW_MS).
 *
 * Kill switch: if the worker ever misbehaves in production, set
 * `selfDestroying: true` in the VitePWA options and deploy. That ships a
 * worker that unregisters itself and clears its caches.
 */

import { registerSW } from "virtual:pwa-register";

/** How often an open app asks the server for a newer worker. */
const UPDATE_CHECK_INTERVAL_MS = 60 * 60 * 1000;

/**
 * How long to wait for the new worker to take control before navigating
 * anyway. The destination still loads correctly under whichever worker is in
 * control; it just may not be the new build yet.
 */
const TAKEOVER_TIMEOUT_MS = 3000;

/**
 * How long a stale-build recovery waits for a freshly found worker to install
 * (it precaches the ~3 MB main chunk) before navigating anyway.
 */
const RECOVERY_INSTALL_TIMEOUT_MS = 8000;

/**
 * A reload asks for a fresh page, so it counts as consent to upgrade: if a new
 * worker is ready within this long of a reload (including one that installs
 * during the reload itself), the page is loaded once more on the new build.
 * Otherwise a reload is served by the old worker, and the waiting worker can't
 * take over until every tab running the old build closes, so F5 alone would
 * never show a deploy. Nobody is mid-question this early in a page they
 * just reloaded.
 */
const RELOAD_UPGRADE_WINDOW_MS = 15_000;

/** This page load was a reload (F5), not a link, typed URL or launch. */
function isReloadLoad(): boolean {
  try {
    const nav = performance.getEntriesByType("navigation")[0] as PerformanceNavigationTiming | undefined;
    return nav?.type === "reload";
  } catch {
    return false;
  }
}

/** sessionStorage key: the target of the last stale-build recovery. */
const RECOVERY_KEY = "lp-stale-build-recovery";

let updateSW: (() => Promise<void>) | undefined;
let registration: ServiceWorkerRegistration | undefined;

/** A recovery is waiting for a new worker to install; take it over at once. */
let recoveryPending = false;

/** A new worker is installed and waiting to be activated. */
let updateWaiting = false;

/**
 * A new worker already controls this page (activated from another tab) while
 * this page still runs the old build.
 */
let reloadPending = false;

/** Where to go once the new worker controls the page. */
let takeoverTarget: string | null = null;
let takeoverTimer: ReturnType<typeof setTimeout> | undefined;

function goTo(target: string): void {
  clearTimeout(takeoverTimer);
  window.location.assign(target);
}

/**
 * Register the service worker. Production builds only: in dev there is no
 * worker, and an old one must not shadow the dev server.
 */
export function initPwa(): void {
  if (!import.meta.env.PROD || !("serviceWorker" in navigator)) return;

  const reloaded = isReloadLoad();

  updateSW = registerSW({
    onNeedRefresh() {
      updateWaiting = true;
      if (recoveryPending && takeoverTarget !== null) {
        recoveryPending = false;
        clearTimeout(takeoverTimer);
        applyUpdateOnNavigation(takeoverTarget);
      } else if (reloaded && performance.now() < RELOAD_UPGRADE_WINDOW_MS) {
        // The follow-up load is a plain navigation (location.assign), not a
        // reload, so this can't loop.
        const here = window.location.pathname + window.location.search + window.location.hash;
        console.log("[pwa] Reloaded with an update ready, loading new build at", here);
        applyUpdateOnNavigation(here);
      }
    },
    onNeedReload() {
      if (takeoverTarget !== null) goTo(takeoverTarget);
      else reloadPending = true;
    },
    onRegisteredSW(_url, reg) {
      if (!reg) return;
      registration = reg;

      // Browsers check for a new worker on full page loads, but an installed
      // app can stay open on one page load for days.
      let lastCheck = Date.now();
      const check = () => {
        if (Date.now() - lastCheck < UPDATE_CHECK_INTERVAL_MS) return;
        lastCheck = Date.now();
        reg.update().catch(() => {
          // Offline, or the server is mid-deploy: try again next time.
        });
      };
      setInterval(check, UPDATE_CHECK_INTERVAL_MS);
      document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "visible") check();
      });
    },
    onRegisterError(error) {
      console.warn("[pwa] Service worker registration failed:", error);
    },
  });
}

/**
 * Router hook: if an update is ready, take over this navigation and finish it
 * as a full page load on the new build. Returns true if it did, in which case
 * the caller must abandon the navigation.
 */
export function applyUpdateOnNavigation(target: string): boolean {
  if (reloadPending) {
    goTo(target);
    return true;
  }
  if (!updateWaiting || !updateSW) return false;

  updateWaiting = false;
  takeoverTarget = target;
  void updateSW(); // → the new worker takes control → onNeedReload → goTo
  takeoverTimer = setTimeout(() => goTo(target), TAKEOVER_TIMEOUT_MS);
  return true;
}

/**
 * A lazily loaded chunk failed to load. Wording differs per browser
 * (Firefox / Chrome / Safari / Vite's CSS preload).
 */
export function isStaleChunkError(error: unknown): boolean {
  const msg = error instanceof Error ? error.message : String(error);
  return /dynamically imported module|Importing a module script failed|Unable to preload CSS/i.test(msg);
}

/**
 * Recover from a failed chunk load by finishing the navigation as a full page
 * load on the current build. Returns false if this target was already tried
 * (a genuine outage, not a stale build), in which case the error stands.
 *
 * The usual cause is a deploy while this page runs the previous build: each
 * deploy is a fresh directory, so the old build's chunks are gone, and Caddy
 * answers the missing .js with index.html. The service worker normally hides
 * this, but it doesn't cover admin chunks (globIgnores) or pages it doesn't
 * control yet. A plain reload isn't enough under an old worker — it would
 * serve the old index.html again — so a waiting worker is activated first.
 */
export function recoverFromStaleBuild(target: string): boolean {
  try {
    if (sessionStorage.getItem(RECOVERY_KEY) === target) return false;
    sessionStorage.setItem(RECOVERY_KEY, target);
  } catch {
    // Storage blocked: recover anyway; the worst case is one extra reload.
  }

  if (applyUpdateOnNavigation(target)) return true;

  const reg = registration;
  if (!reg || !updateSW) {
    goTo(target);
    return true;
  }

  // No new worker known yet: ask for one. If it shows up, onNeedRefresh takes
  // over as soon as it has installed.
  takeoverTarget = target;
  recoveryPending = true;
  takeoverTimer = setTimeout(() => goTo(target), RECOVERY_INSTALL_TIMEOUT_MS);
  reg
    .update()
    .catch(() => {})
    .then(() => {
      if (recoveryPending && !reg.installing && !reg.waiting) goTo(target);
    });
  return true;
}

/** A navigation succeeded: a later failure on the same target may retry. */
export function clearStaleBuildRecovery(): void {
  try {
    sessionStorage.removeItem(RECOVERY_KEY);
  } catch {
    // ignore
  }
}
